const menus = {
    monday: [
        {name:"Latte", price:"$60", img:"data:image/jpeg;base64,"},
        {name:"Cake", price:"$50", img:"data:image/jpeg;base64,"}
    ],
    tuesday: [
        {name:"Tea", price:"$40", img:"data:image/jpeg;base64,"},
        {name:"Cookie", price:"$30", img:"data:image/jpeg;base64,"}
    ],
    wednesday: [
        {name:"Milk", price:"$35", img:"data:image/jpeg;base64,"},
        {name:"Brownie", price:"$45", img:"data:image/jpeg;base64,"}
    ],
    thursday: [
        {name:"Mocha", price:"$65", img:"data:image/jpeg;base64,"},
        {name:"Sandwich", price:"$70", img:"data:image/jpeg;base64,"}
    ],
    friday: [
        {name:"Espresso", price:"$50", img:"data:image/jpeg;base64,"},
        {name:"Donut", price:"$40", img:"data:image/jpeg;base64,"}
    ],
    saturday: [
        {name:"Cold Brew", price:"$75", img:"data:image/jpeg;base64,"},
        {name:"Waffle", price:"$80", img:"data:image/jpeg;base64,"}
    ],
    sunday: [
        {name:"Milk Tea", price:"$55", img:"data:image/jpeg;base64,"},
        {name:"Croissant", price:"$60", img:"data:image/jpeg;base64,"}
    ]
};

function changeMenu(day){
    const menu = document.getElementById("menu");
    menu.innerHTML = "";

    menus[day].forEach(item => {
        const div = document.createElement("div");
        div.className = "menu-card";

        div.innerHTML = `
            <img src="${item.img}">
            <h3>${item.name}</h3>
            <p>${item.price}</p>
        `;

        menu.appendChild(div);
    });
}

changeMenu("monday");
